INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvordan kom Hitler til magten i Germany?","options":["Han blev demokratisk valgt som kansler i 1933 og udnyttede derefter en krise til at omdanne Germany til et diktatur","Han gennemfoerte et militaerkup og tog magten med magt","Han arvede magten fra den tidligere kansler","Han blev valgt af militaeret til at lede Germany"],"correct":"Han blev demokratisk valgt som kansler i 1933 og udnyttede derefter en krise til at omdanne Germany til et diktatur","accepted_answers":["Han blev demokratisk valgt som kansler i 1933 og udnyttede derefter en krise til at omdanne Germany til et diktatur"],"review_text":"Hitler kom til magten ad demokratisk vej i januar 1933 da han blev udnaevnt til kansler. Derefter brugte han Rigsdagsbranden til at faa undtagelsesbefoejelser og Enablingsloven til at goere sig til diktator. Det var en gradvis overtagelse ikke et pludseligt kup."}'::jsonb,
  'mc','short','{"concepts":["Hitler","magtovertagelse","demokratisk","kansler","diktatur"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_2"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_2',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var kernen i den nazistiske ideologi?","options":["Racistisk nationalisme der satte den ariske race over alle andre med antisemitisme som centralt element","Et okonomisk system baseret paa fri handel og kapitalisme","En demokratisk bevaegelse der ville give folket mere indflydelse","En religioes bevaegelse baseret paa protestantisk kristendom"],"correct":"Racistisk nationalisme der satte den ariske race over alle andre med antisemitisme som centralt element","accepted_answers":["Racistisk nationalisme der satte den ariske race over alle andre med antisemitisme som centralt element"],"review_text":"Nazismen byggede paa racetenkning. Den ariske race sattes over alle andre. Joder, sigojnere og handicappede blev betragtet som mindrevaerdige. Antisemitisme var ikke en sidebemaekning men kernelementet i ideologien."}'::jsonb,
  'mc','short','{"concepts":["nazisme","raceideologi","antisemitisme","arisk","ideologi"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_2"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_2',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvornaar og med hvad startede Anden Verdenskrig i Europa?","options":["1. september 1939 da Germany invaderede Polen og England og Frankrig erklaerede Germany krig","1. september 1938 da Germany annekterede Oestrig","7. december 1941 da Japan angreb Pearl Harbor","10. maj 1940 da Germany invaderede Frankrig"],"correct":"1. september 1939 da Germany invaderede Polen og England og Frankrig erklaerede Germany krig","accepted_answers":["1. september 1939 da Germany invaderede Polen og England og Frankrig erklaerede Germany krig"],"review_text":"Den 1. september 1939 invaderede Germany Polen. To dage senere erklaerede England og Frankrig Germany krig. Det var den officielle start paa Anden Verdenskrig i Europa."}'::jsonb,
  'mc','short','{"concepts":["krigens udbrud","Polen","1939","England","Frankrig"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_2"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_2',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvornaar besatte Germany Danmark og hvad skete der?","options":["9. april 1940 invaderede Germany Danmark og den danske regering valgte at samarbeje for at beskytte befolkningen","9. april 1940 invaderede Germany Danmark og den danske haer kaeampede i to uger","1. maj 1941 invaderede Germany Danmark som reaktion paa dansk modstand","Danmark var aldrig besat af Germany under Anden Verdenskrig"],"correct":"9. april 1940 invaderede Germany Danmark og den danske regering valgte at samarbeje for at beskytte befolkningen","accepted_answers":["9. april 1940 invaderede Germany Danmark og den danske regering valgte at samarbeje for at beskytte befolkningen"],"review_text":"Den 9. april 1940 invaderede Germany Danmark. Den danske haer kaeampede kun i faa timer. Regeringen kapitulerede for at undgaa blodbad og beholde mest mulig selvstyreret. Det var starten paa et kompliceret besaettelsesforhold."}'::jsonb,
  'mc','short','{"concepts":["dansk besaettelse","9. april 1940","samarbejdspolitik","kapitulation"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_2"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_2',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var Holocaust?","options":["Det systematiske folkedrab paa ca. 6 millioner joder og millioner af andre grupper gennemfoert af Nazi-Germany","Et massedrab paa franske civile under den tyske besaettelse","En serie koncentrationslejre i Rusland under Stalins styre","Betegnelse for de allieredes bombardementer af tyske byer"],"correct":"Det systematiske folkedrab paa ca. 6 millioner joder og millioner af andre grupper gennemfoert af Nazi-Germany","accepted_answers":["Det systematiske folkedrab paa ca. 6 millioner joder og millioner af andre grupper gennemfoert af Nazi-Germany"],"review_text":"Holocaust var den planlagte og systematiske udrottelse af Europas joder. Ca. 6 millioner joder wurde myrdede. Dertil kom sigojnere, handicappede, homoseksuelle og politiske modstandere. Det er den storste planlagte massedrab i historien."}'::jsonb,
  'mc','short','{"concepts":["Holocaust","folkedrab","joder","systematisk","Nazi-Germany"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_2"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_2',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad endte Anden Verdenskrig i Europa?","options":["Germanys ubetingede kapitulation den 8. maj 1945 da de allierede had besat det meste af Germany","En fredsaftale forhandlet af alle parter i Geneve i april 1945","Hitlers aftale om vaabenstilstand i marts 1945","Den sovjetiske overtagelse af alle europaeiske lande i 1945"],"correct":"Germanys ubetingede kapitulation den 8. maj 1945 da de allierede had besat det meste af Germany","accepted_answers":["Germanys ubetingede kapitulation den 8. maj 1945 da de allierede had besat det meste af Germany"],"review_text":"Den 8. maj 1945 kapitulerede Germany ubetinget. Det er fejret som Victory in Europe Day. I Asien fortsatte krigen mod Japan indtil den japanske kapitulation i august 1945 efter atombomberne over Hiroshima og Nagasaki."}'::jsonb,
  'mc','short','{"concepts":["krigens afslutning","8. maj 1945","kapitulation","V-E Day"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_2"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_2',8,1
);

